#[cfg(test)]mod resurrection61_controller_development_tests {
 use super::*;
 fn ready()->LoginController {let mut c=LoginController::default();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();c.state.world.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}c.state.phase=LoginPhase::BattlePending;c.state.game_connected=true;c.state.selected_source=Some("isolated".into());c.state.selected_character=Some("fixture".into());c.state.inventory.owner=Some(super::super::native_inventory::Owner{connection:c.transport.snapshot().epoch,selection:1,character:"fixture".into()});let id=c.state.world.own_actor().unwrap().id;c.state.world.actors.get_mut(&id).unwrap().dead=true;c.state.world.hp=Some([0,100]);c}
 #[test]fn controller_receives_dead_question_and_interrupt_does_not_reuse_old_command_id(){let mut c=ready();c.accept_game(&[36,65,1]).unwrap();let first=c.resurrection_prompt().unwrap().token();c.interrupt_world_actions();assert!(c.resurrection_prompt().is_none());c.accept_game(&[36,65,1]).unwrap();assert_ne!(first.command_id(true),c.resurrection_prompt().unwrap().token().command_id(true));}
 #[test]fn revive_effect_then_S11_keeps_received_visuals_without_predicting_hp_or_ack_from_gfx(){let mut c=ready();let own=c.state.world.own_actor().unwrap().clone();c.accept_game(&[36,65,1]).unwrap();for gfx in [3944u16,230]{let mut b=vec![0x37];b.extend(own.id.to_le_bytes());b.extend(gfx.to_le_bytes());c.accept_game(&b).unwrap();}assert!(c.resurrection_prompt().is_some());assert_eq!(c.state.world.hp,Some([0,100]));assert!(c.state.world.effects.iter().all(|e|e.target.is_none()));let mut b=vec![0x11];b.extend(own.id.to_le_bytes());b.push(0);b.extend(2_u32.to_le_bytes());b.extend(own.graphics.to_le_bytes());c.accept_game(&b).unwrap();assert!(c.resurrection_prompt().is_none());assert!(!c.state.world.own_actor().unwrap().dead);assert_eq!(c.state.world.hp,Some([0,100]));assert_eq!(c.state.world.effects.len(),2);}
}
